	/*
     * @param	event CreateVerifiedAddressEvent
     */
    @EventHandler( payloadType=CreateVerifiedAddressEvent.class )
    public void handle( CreateVerifiedAddressEvent event) {
	    LOGGER.info("handling CreateVerifiedAddressEvent - " + event );
	    VerifiedAddress entity = new VerifiedAddress();
            entity.setVerifiedAddressId( event.getVerifiedAddressId() );
            entity.setAddress( event.getAddress() );
            entity.setVerifiedAt( event.getVerifiedAt() );
            entity.setVerificationStatus( event.getVerificationStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllVerifiedAddress( entity );
    }

    /*
     * @param	event UpdateVerifiedAddressEvent
     */
    @EventHandler( payloadType=UpdateVerifiedAddressEvent.class )
    public void handle( UpdateVerifiedAddressEvent event) {
    	LOGGER.info("handling UpdateVerifiedAddressEvent - " + event );
    	
	    VerifiedAddress entity = new VerifiedAddress();
            entity.setVerifiedAddressId( event.getVerifiedAddressId() );
            entity.setAddress( event.getAddress() );
            entity.setVerifiedAt( event.getVerifiedAt() );
            entity.setKycProfile( event.getKycProfile() );
            entity.setVerificationStatus( event.getVerificationStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindVerifiedAddress( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllVerifiedAddress( entity );        
    }
    
