    public List<VerifiedAddress> handle( FindAllVerifiedAddressQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindVerifiedAddress,
 * but only if the id matches
 *
 * @param		entity	VerifiedAddress
 */
	protected void emitFindVerifiedAddress( VerifiedAddress entity ) {
		LOGGER.info("handling emitFindVerifiedAddress" );
		
	    queryUpdateEmitter.emit(FindVerifiedAddressQuery.class,
	                            query -> query.getFilter().getVerifiedAddressId().equals(entity.getVerifiedAddressId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllVerifiedAddress
	 * 
	 * @param		entity	VerifiedAddress
	 */
	protected void emitFindAllVerifiedAddress( VerifiedAddress entity ) {
		LOGGER.info("handling emitFindAllVerifiedAddress" );
		
	    queryUpdateEmitter.emit(FindAllVerifiedAddressQuery.class,
	                            query -> true,
	                            entity);
	}

